create extension if not exists pgcrypto;create table if not exists public.products(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,model_no text,category text not null default 'other',price numeric(12,2),short_description text not null,description text,specifications jsonb not null default '{}'::jsonb,image_url text,pdf_url text,seo_title text,seo_keywords text,published boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());alter table public.products enable row level security;grant select on public.products to anon;grant select,insert,update,delete on public.products to authenticated;drop policy if exists "Public can read published products" on public.products;create policy "Public can read published products" on public.products for select to anon,authenticated using(published=true or auth.role()='authenticated');drop policy if exists "Signed in admins can insert products" on public.products;create policy "Signed in admins can insert products" on public.products for insert to authenticated with check(auth.uid() is not null);drop policy if exists "Signed in admins can update products" on public.products;create policy "Signed in admins can update products" on public.products for update to authenticated using(auth.uid() is not null) with check(auth.uid() is not null);drop policy if exists "Signed in admins can delete products" on public.products;create policy "Signed in admins can delete products" on public.products for delete to authenticated using(auth.uid() is not null);insert into storage.buckets(id,name,public)values('product-assets','product-assets',true)on conflict(id)do update set public=true;drop policy if exists "Public can view product assets" on storage.objects;create policy "Public can view product assets" on storage.objects for select to public using(bucket_id='product-assets');drop policy if exists "Authenticated admins can upload product assets" on storage.objects;create policy "Authenticated admins can upload product assets" on storage.objects for insert to authenticated with check(bucket_id='product-assets' and auth.role()='authenticated');drop policy if exists "Authenticated admins can update product assets" on storage.objects;create policy "Authenticated admins can update product assets" on storage.objects for update to authenticated using(bucket_id='product-assets' and auth.role()='authenticated')with check(bucket_id='product-assets' and auth.role()='authenticated');drop policy if exists "Authenticated admins can delete product assets" on storage.objects;create policy "Authenticated admins can delete product assets" on storage.objects for delete to authenticated using(bucket_id='product-assets' and auth.role()='authenticated');insert into public.products(name,slug,category,short_description,published)values('Hot Air Oven','hot-air-oven','heating','Controlled dry-heat equipment for laboratory heating, drying and sterilization workflows.',true),('BOD Incubator','bod-incubator','incubation','Stable temperature-controlled incubation equipment for biological and laboratory testing.',true),('Water Bath','water-bath','heating','Uniform and controlled temperature heating for samples, reagents and routine laboratory work.',true)on conflict(slug)do nothing;